const input = $input.first()?.json || {};
const body = input.body;

function fail(message) {
  throw new Error('VALIDATION_ERROR: ' + message);
}
function codePointLength(value) {
  return [...String(value)].length;
}
function optionalSingleLine(name, maxLength = 256) {
  const raw = body[name];
  if (raw === undefined || raw === null || raw === '') return '';
  if (typeof raw !== 'string') fail(name + ' 必须是字符串');
  const value = raw.trim().replace(/[ \t]+/g, ' ');
  if (!value || /[\r\n]/.test(value) || /\\n/.test(value) || codePointLength(value) > maxLength) {
    fail(name + ' 必须是最多 ' + maxLength + ' 个 Unicode 字符的非空单行文本');
  }
  return value;
}

if (!body || typeof body !== 'object' || Array.isArray(body)) fail('请求体必须是 JSON 对象');
const contentPolicyVersion = String(body.contentPolicyVersion || body.policyVersion || '').trim();
if (!['merchroute-ozon-content-v2','merchroute-ozon-content-v3','merchroute-ozon-content-v4'].includes(contentPolicyVersion)) fail('contentPolicyVersion 必须是显式且受支持的冻结版本');
if (typeof body.content !== 'string') fail('content 必须是字符串');
const content = body.content.trim().replace(/[ \t]+/g, ' ');
if (!content) fail('content 不能为空');
if (/[\r\n]/.test(content) || /\\n/.test(content)) fail('content 必须是单行文本');
if (codePointLength(content) > 1000) fail('content 最多 1000 个 Unicode 字符');
if (typeof body.language !== 'string') fail('language 必须是字符串');
const language = body.language.trim().replace(/[ \t]+/g, ' ');
if (!language) fail('language 不能为空');
if (/[\r\n]/.test(language) || /\\n/.test(language) || codePointLength(language) > 64) {
  fail('language 必须是最多 64 个 Unicode 字符的单行文本');
}
const maxLength = Number(body.maxLength);
if (!Number.isInteger(maxLength) || maxLength < 1 || maxLength > 200) {
  fail('maxLength 必须是 1 到 200 的整数');
}
let requestId = '';
if (body.requestId !== undefined && body.requestId !== null) {
  if (typeof body.requestId !== 'string') fail('requestId 必须是字符串');
  requestId = body.requestId.trim();
  if (!requestId || /[\r\n]/.test(requestId) || /\\n/.test(requestId) || codePointLength(requestId) > 128) {
    fail('requestId 必须是最多 128 个 Unicode 字符的非空单行文本');
  }
}
const productTypeRu = optionalSingleLine('productTypeRu');
const brand = optionalSingleLine('brand');
const model = optionalSingleLine('model');
let importantCharacteristics = [];
if (body.importantCharacteristics !== undefined && body.importantCharacteristics !== null && body.importantCharacteristics !== '') {
  const rawValues = Array.isArray(body.importantCharacteristics) ? body.importantCharacteristics : [body.importantCharacteristics];
  if (rawValues.length > 20) fail('importantCharacteristics 最多包含 20 项');
  importantCharacteristics = rawValues.map((raw, index) => {
    if (typeof raw !== 'string') fail('importantCharacteristics[' + index + '] 必须是字符串');
    const value = raw.trim().replace(/[ \t]+/g, ' ');
    if (!value || /[\r\n]/.test(value) || /\\n/.test(value) || codePointLength(value) > 256) {
      fail('importantCharacteristics[' + index + '] 必须是最多 256 个 Unicode 字符的非空单行文本');
    }
    return value;
  });
}

const context = {
  ...(productTypeRu ? { productTypeRu } : {}),
  ...(brand ? { brand } : {}),
  ...(model ? { model } : {}),
  ...(importantCharacteristics.length ? { importantCharacteristics } : {})
};
const sysPrompt = [
  '你是一名专业的 OZON 俄文商品标题翻译助手。',
  '准确、自然地把原文翻译为用户指定语言；优先保留品类、品牌、型号及重要特征，不得添加输入中不存在的事实。',
  '翻译标题必须是单行文本，不得包含回车、换行、Markdown、解释、前后缀或引号。',
  'contentTranslate 的 Unicode 字符总数不得超过 maxLength；必要时精简修饰语，但必须保留核心品类。',
  '必须只输出一个合法 JSON 对象。调用方 S007 要求外层字段 messageContent；messageContent 必须是一个 JSON 字符串，解析后只能包含字符串字段 contentTranslate。',
  '外层格式必须精确类似：{"messageContent":"{\\"contentTranslate\\":\\"翻译结果\\"}"}。禁止输出代码块或任何额外内容。'
].join('\n');
const userPrompt = '请翻译以下 JSON 数据中的 content，并严格遵守 language、maxLength、contentPolicyVersion 和可选商品上下文：\n' + JSON.stringify({ content, language, maxLength, contentPolicyVersion, ...context });

return [{ json: {
  content,
  language,
  maxLength,
  requestId,
  contentPolicyVersion,
  productTypeRu,
  brand,
  model,
  importantCharacteristics,
  sysPrompt,
  userPrompt
} }];

const response = $input.first()?.json || {};
const request = $('Validate Translation Request').first()?.json || {};
const contentPolicyVersion = String(request.contentPolicyVersion || '').trim();
if (!['merchroute-ozon-content-v2','merchroute-ozon-content-v3','merchroute-ozon-content-v4'].includes(contentPolicyVersion)) throw new Error('OUTPUT_INVALID: 标题翻译缺少受支持的冻结内容策略版本');
const raw = response.messageContent;

const titleCjk = /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]/u;
const titleInvalidPlatformText = /[\p{Extended_Pictographic}\p{Private_Use}\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/u;
const titleHiddenFormat = /[\u00A0\p{Cf}]/u;
const titleAllowedCharacters = /^[A-Za-zА-Яа-яЁё0-9 .,:;()\-/&"!?]+$/u;
const titleForbiddenSymbol = /[™©®\[\]=\\«»]/u;
const titleUrl = /(?:https?:\/\/|www\.)\S+|\b[a-z0-9-]+\.(?:ru|com|net|org|io|shop|store)\b/iu;
const titleAdvertising = /(?:^|[^\p{L}])(?:акци[яи]|распродаж\p{L}*|скидк\p{L}*|выгодн(?:ое|ые)\s+предложени\p{L}*|лучший\s+(?:товар|выбор)|сам(?:ый|ая|ое|ые)\s+лучший|топ(?:[- ]?товар)?|хит продаж|sale|discount|best price)(?=$|[^\p{L}])/iu;
const titlePrice = /(?:^|[^\p{L}\p{N}])(?:цен[аы]|(?:от\s+)?\d[\d\s.,]*\s*(?:₽|руб\.?|р\.?|usd|eur))(?=$|[^\p{L}\p{N}])|[$€]/iu;
const titleImitationV2 = /(?:^|[^\p{L}\p{N}])(?:аналог\p{L}*|реплик\p{L}*|копи[яи]\p{L}*|подделк\p{L}*|имитац\p{L}*|1\s*:\s*1|replica|imitation|counterfeit)(?=$|[^\p{L}\p{N}])/iu;
const titleImitationV3 = /(?:^|[^\p{L}\p{N}])(?:аналог(?:а|у|ом|е|и|ов|ам|ами|ах)?|реплик\p{L}*|копи[яи]\p{L}*|подделк\p{L}*|имитац\p{L}*|1\s*:\s*1|replica|imitation|counterfeit)(?=$|[^\p{L}\p{N}])/iu;
const titleImitation = contentPolicyVersion === 'merchroute-ozon-content-v2' ? titleImitationV2 : titleImitationV3;
const titleIssues = (value) => {
  const text = String(value ?? '');
  const issues = [];
  if (!text) issues.push('EMPTY');
  if ([...text].length > 200) issues.push('TOO_LONG');
  if (/[\r\n]/.test(text) || /\\n/.test(text)) issues.push('MULTILINE');
  if (titleCjk.test(text)) issues.push('CJK');
  if (titleInvalidPlatformText.test(text)) issues.push('INVALID_CHARACTER');
  if (titleHiddenFormat.test(text)) issues.push('HIDDEN_CHARACTER');
  if (/<[^>]*>/.test(text)) issues.push('UNSUPPORTED_HTML');
  if (titleUrl.test(text)) issues.push('EXTERNAL_LINK');
  if (titleAdvertising.test(text)) issues.push('ADVERTISING');
  if (titlePrice.test(text)) issues.push('PRICE_INFORMATION');
  if (titleImitation.test(text)) issues.push('IMITATION_CLAIM');
  if (titleForbiddenSymbol.test(text)) issues.push('FORBIDDEN_SYMBOL');
  if (!titleAllowedCharacters.test(text)) issues.push('INVALID_TITLE_CHARACTER');
  if (text && !/^[A-ZА-ЯЁ]/u.test(text)) issues.push('TITLE_INITIAL_NOT_UPPERCASE');
  if (text.split(' ').some((word) => [...word].length > 27)) issues.push('TITLE_WORD_TOO_LONG');
  const counts = new Map();
  for (const word of text.toLocaleLowerCase('ru-RU').match(/[a-zа-яё]{4,}/giu) || []) {
    const count = (counts.get(word) || 0) + 1;
    counts.set(word, count);
    if (count >= 3) issues.push('KEYWORD_STUFFING');
  }
  return [...new Set(issues)];
};

function invalid(message) {
  throw new Error('OUTPUT_INVALID: ' + message);
}
if (typeof raw !== 'string' || !raw.trim()) invalid('S007 未返回非空字符串 messageContent');
let parsed;
try { parsed = JSON.parse(raw.trim()); } catch (_) { invalid('S007 messageContent 不是合法的 contentTranslate JSON'); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) invalid('翻译结果必须是 JSON 对象');
const keys = Object.keys(parsed);
if (keys.length !== 1 || keys[0] !== 'contentTranslate' || typeof parsed.contentTranslate !== 'string') {
  invalid('翻译结果必须且只能包含字符串字段 contentTranslate');
}
const contentTranslate = parsed.contentTranslate;
const policyIssues = titleIssues(contentTranslate);
const blockingIssues = policyIssues.filter((issue) => issue !== 'TOO_LONG');
if (blockingIssues.length) invalid('contentTranslate 不符合 OZON 标题合同 [' + blockingIssues.join(', ') + ']');
const translatedLength = [...contentTranslate].length;
const maxLength = Number(request.maxLength);
return [{ json: {
  contentTranslate,
  model: response.model || null,
  usage: response.usage || null,
  finishReason: response.finishReason || null,
  requestId: request.requestId || null,
  contentPolicyVersion,
  translatedLength,
  originalTranslatedLength: translatedLength,
  maxLength,
  needsShortening: policyIssues.includes('TOO_LONG') || translatedLength > maxLength,
  shorteningAttempted: false
} }];

const initial = $input.first()?.json || {};
const request = $('Validate Translation Request').first()?.json || {};
if (initial.needsShortening !== true || initial.shorteningAttempted === true) throw new Error('OUTPUT_INVALID: 非法的标题缩短状态');
const sysPrompt = [
  '你正在执行唯一一次 OZON 标题长度纠偏。',
