  'contentTranslate 必须是单行，Unicode 字符数不得超过 maxLength。',
  '只输出 S007 所需 JSON：{"messageContent":"{\\"contentTranslate\\":\\"缩短后的标题\\"}"}。'
].join('\n');
const userPrompt = '请将下列俄文标题缩短到上限内；这是唯一一次纠偏：\n' + JSON.stringify({
  contentTranslate: initial.contentTranslate,
  actualLength: Number(initial.translatedLength),
  maxLength: Number(request.maxLength),
  productTypeRu: request.productTypeRu || undefined,
  brand: request.brand || undefined,
  model: request.model || undefined,
  importantCharacteristics: request.importantCharacteristics?.length ? request.importantCharacteristics : undefined
});
return [{ json: { ...initial, sysPrompt, userPrompt, shorteningAttempted: true } }];

