function invalid(message) {
  throw new Error('OUTPUT_INVALID: ' + message);
}
if (typeof raw !== 'string' || !raw.trim()) invalid('缩短纠偏未返回非空字符串 messageContent');
let parsed;
try { parsed = JSON.parse(raw.trim()); } catch (_) { invalid('缩短纠偏 messageContent 不是合法 JSON'); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) invalid('缩短纠偏结果必须是 JSON 对象');
const keys = Object.keys(parsed);
if (keys.length !== 1 || keys[0] !== 'contentTranslate' || typeof parsed.contentTranslate !== 'string') {
