const input = $input.first()?.json || {};
const rawMessage = String(input.error?.message || input.error || input.message || '请求参数无效');
const message = rawMessage.replace(/^VALIDATION_ERROR:\s*/, '').replace(/\s*\[line \d+\]\s*$/, '').trim() || '请求参数无效';
let requestId = null;
try {
  const candidate = $('Translation Title Webhook').first()?.json?.body?.requestId;
  if (typeof candidate === 'string' && candidate.trim()) requestId = candidate.trim();
} catch (_) {}
return [{ json: { error: 'VALIDATION_ERROR', message, requestId, retryable: false, httpStatus: 400 } }];

const input = $input.first()?.json || {};
const rawError = input.error && typeof input.error === 'object' ? input.error : {};
const rawMessage = String(rawError.message || input.error || input.message || '标题翻译上游调用失败');
const statusCandidates = [input.statusCode, input.httpCode, rawError.statusCode, rawError.httpCode, rawError.status];
const statusCode = statusCandidates.map(Number).find((value) => Number.isInteger(value) && value >= 100 && value <= 599)
  || Number(rawMessage.match(/(?:HTTP\s*)?([45]\d\d)/i)?.[1] || 0);
const upper = rawMessage.toUpperCase();
const retryAfterMs = Math.max(0, Number(input.retryAfterMs || rawError.retryAfterMs || 0));
let httpStatus = 502;
let error = 'TRANSLATION_FAILED';
let message = '标题翻译失败，请检查错误详情后再决定是否重试';
