  httpStatus = statusCode === 400 || statusCode === 422 ? 422 : statusCode;
  error = 'TRANSLATION_UPSTREAM_REJECTED';
  message = '翻译模型拒绝了本次标题请求';
} else if (statusCode === 408 || /ETIMEDOUT|ESOCKETTIMEDOUT|TIMEOUT|超时/.test(upper)) {
  httpStatus = 504;
  error = 'TRANSLATION_UPSTREAM_TIMEOUT';
  message = '标题翻译上游超时，请稍后重试';
  retryable = true;
} else if (statusCode === 429 || /RATE.?LIMIT|TOO MANY REQUESTS/.test(upper)) {
  httpStatus = 429;
  error = 'TRANSLATION_RATE_LIMITED';
  message = '标题翻译上游限流，请稍后重试';
  retryable = true;
} else if (statusCode >= 500 && statusCode <= 599) {
  httpStatus = 502;
  error = 'TRANSLATION_UPSTREAM_5XX';
  message = '标题翻译上游暂时不可用，请稍后重试';
  retryable = true;
} else if (/ENOTFOUND|EAI_AGAIN|ECONNRESET|ECONNREFUSED|ECONNABORTED|EHOSTUNREACH|ENETUNREACH|SOCKET HANG UP|NETWORK (?:ERROR|FAIL)|FETCH FAILED|连接(?:中断|失败|重置)|断网/.test(upper)) {
  httpStatus = 502;
  error = 'TRANSLATION_NETWORK_ERROR';
  message = '标题翻译网络暂时不可用，请稍后重试';
  retryable = true;
}
let requestId = null;
try { requestId = $('Validate Translation Request').first()?.json?.requestId || null; } catch (_) {}
return [{ json: { error, message, requestId, retryable, retryAfterMs: retryAfterMs || undefined, httpStatus, auditMessage: rawMessage.slice(0, 500) } }];

const input = $input.first()?.json || {};
