let requestId = null;
let initial = {};
try { requestId = $('Validate Translation Request').first()?.json?.requestId || null; } catch (_) {}
try { initial = $('Parse Initial Translation').first()?.json || {}; } catch (_) {}
return [{ json: {
  error: 'TRANSLATION_OUTPUT_INVALID',
  message: '翻译模型返回内容不符合 OZON 标题合同',
  requestId,
  retryable: false,
  httpStatus: 422,
  actualLength: Number(initial.translatedLength || 0) || undefined,
  maxLength: Number(initial.maxLength || 0) || undefined,
  shorteningAttempted: Boolean(initial.needsShortening),
  auditMessage: rawMessage.slice(0, 500)
} }];
